            ["OfflineFact"] = element => Wire.Run(() => Codec.EncodeOfflineFact(Codec.ReadOfflineFact(element, "$"))),
            ["WorkerCommand"] = element => Wire.Run(() => Codec.EncodeWorkerCommand(Codec.ReadWorkerCommand(element, "$"))),
            ["WorkerReply"] = element => Wire.Run(() => Codec.EncodeWorkerReply(Codec.ReadWorkerReply(element, "$"))),
        };
}
